import{f as o,J as d,o as t,c as n,a6 as s,b as r,w as a,a as l,K as h,a7 as c}from"./chunks/framework.Dd1qhYRL.js";const q=JSON.parse('{"title":"noorm sql","description":"","frontmatter":{},"headers":[],"relativePath":"cli/sql.md","filePath":"cli/sql.md"}'),p={name:"cli/sql.md"};function g(k,e,u,b,m,y){const i=d("Mermaid");return t(),n("div",null,[e[1]||(e[1]=s(`<h1 id="noorm-sql" tabindex="-1">noorm sql <a class="header-anchor" href="#noorm-sql" aria-label="Permalink to “noorm sql”">​</a></h1><p>Run a SQL statement against a config from the command line, and manage the saved query history.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;SELECT party_id, order_no FROM sales_order LIMIT 2&quot;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Columns: party_id, order_no</span></span>
<span class="line"><span>{&quot;party_id&quot;:1,&quot;order_no&quot;:1}</span></span>
<span class="line"><span>{&quot;party_id&quot;:1,&quot;order_no&quot;:2}</span></span>
<span class="line"><span>2 rows returned (3ms)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Subcommand</th><th>Does</th></tr></thead><tbody><tr><td><code>query</code></td><td>Runs one SQL statement, or a file of them, against the active config</td></tr><tr><td><code>history</code></td><td>Lists recent queries from the SQL terminal</td></tr><tr><td><code>clear</code></td><td>Deletes saved history</td></tr><tr><td><code>repl</code></td><td>Opens the TUI on the SQL terminal: <a href="/cli/sql-repl.html"><code>noorm sql repl</code></a></td></tr></tbody></table><p>The role your channel holds on the config decides which statements run. The statement is classified as read, write, or DDL; see <a href="/guide/environments/configs.html#access-roles">access roles</a>.</p><h2 id="can-i-skip-the-word-query" tabindex="-1">Can I skip the word <code>query</code>? <a class="header-anchor" href="#can-i-skip-the-word-query" aria-label="Permalink to “Can I skip the word query?”">​</a></h2><p>Yes, when the first word after <code>sql</code> that is not a flag starts with a SQL verb. noorm inserts <code>query</code> for you:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;SELECT 1&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # runs: noorm sql query &quot;SELECT 1&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;SELECT 1 AS one&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # runs: noorm sql query --json &quot;SELECT 1 AS one&quot;</span></span></code></pre></div><p>That word picks one of three outcomes:</p>`,10)),(t(),r(c,null,{default:a(()=>[h(i,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22noorm%20sql%20...%22%5D%20--%3E%20B%7B%22first%20token%20after%20sql%3Cbr%2F%3Ethat%20is%20not%20a%20flag%22%7D%0A%20%20%20%20B%20--%3E%7C%22query%2C%20history%2C%3Cbr%2F%3Eclear%2C%20repl%22%7C%20C%5B%22that%20subcommand%20runs%22%5D%0A%20%20%20%20B%20--%3E%7C%22starts%20with%20a%20SQL%20verb%22%7C%20D%5B%22query%20is%20inserted%22%5D%0A%20%20%20%20B%20--%3E%7C%22anything%20else%22%7C%20E%5B%22Unknown%20command%2C%20exit%201%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<p>The rewrite is positional and never touches the SQL or the flags. A SQL verb is one of <code>SELECT</code>, <code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>, <code>MERGE</code>, <code>WITH</code>, <code>CREATE</code>, <code>DROP</code>, <code>ALTER</code>, <code>TRUNCATE</code>, <code>EXEC</code>, <code>EXECUTE</code>, <code>CALL</code>, <code>SHOW</code>, <code>EXPLAIN</code>, <code>GRANT</code>, <code>REVOKE</code>, <code>COMMENT</code>, <code>PRAGMA</code>, <code>VACUUM</code>, <code>ANALYZE</code>, <code>BEGIN</code>, <code>COMMIT</code>, <code>ROLLBACK</code>, <code>SAVEPOINT</code>, or <code>USE</code>, in any case.</p><p>A flag that takes a value puts the value first, so the rewrite misses:</p><table tabindex="0"><thead><tr><th>Typed</th><th>Result</th><th>Write instead</th></tr></thead><tbody><tr><td><code>noorm sql -c prod &quot;SELECT 1&quot;</code></td><td><code>Unknown command prod</code>, exit 1</td><td><code>noorm sql query -c prod &quot;SELECT 1&quot;</code></td></tr><tr><td><code>noorm sql -f reports/monthly.sql</code></td><td><code>Unknown command reports/monthly.sql</code>, exit 1</td><td><code>noorm sql query -f reports/monthly.sql</code></td></tr><tr><td><code>noorm sql --json &quot;SELECT 1&quot;</code></td><td>Works. <code>--json</code> takes no value</td><td></td></tr></tbody></table><h2 id="sql-query" tabindex="-1">sql query <a class="header-anchor" href="#sql-query" aria-label="Permalink to “sql query”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>noorm sql query [&lt;sql&gt;] [--file &lt;path&gt;] [--config &lt;name&gt;] [--json]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>&lt;sql&gt;</code></td><td>The statement. Optional when <code>--file</code> is given</td></tr><tr><td><code>--file &lt;path&gt;</code>, <code>-f &lt;path&gt;</code></td><td>Read the SQL from a file. It wins over <code>&lt;sql&gt;</code></td></tr><tr><td><code>--config &lt;name&gt;</code>, <code>-c &lt;name&gt;</code></td><td>Run against this config instead of the active one</td></tr><tr><td><code>--json</code></td><td>Print <code>{&quot;success&quot;:true,&quot;columns&quot;:[…],&quot;rows&quot;:[…],&quot;durationMs&quot;:…}</code> on stdout</td></tr></tbody></table><p>Human output is <code>Columns:</code>, one JSON line per row, then <code>N row(s) returned (Xms)</code>. A statement that changes rows prints <code>Rows affected: N</code> instead. <code>--json</code> is a per-subcommand flag: write it after <code>query</code>, not before <code>sql</code>. The <a href="/cli/flags.html">flag rules</a> explain why.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reports/monthly.sql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td>No <code>&lt;sql&gt;</code> and no <code>--file</code></td><td><code>No query provided. Usage: noorm sql &quot;SELECT ...&quot;</code>, exit 2</td></tr><tr><td><code>--file</code> cannot be read</td><td><code>Failed to read SQL file: &lt;path&gt;: &lt;reason&gt;</code>, exit 2</td></tr><tr><td>The database rejects the statement</td><td><code>Query failed: &lt;message&gt;</code>, exit 1</td></tr><tr><td>Your role does not allow that class of statement</td><td>The policy message, exit 1</td></tr><tr><td>Cannot connect</td><td><code>Failed to connect: &lt;message&gt;</code>, exit 1</td></tr></tbody></table><p><code>sql query</code> writes nothing to history. It is the headless path, and persisting query text and returned rows on a build agent is an exposure nobody asked for.</p><h2 id="sql-history" tabindex="-1">sql history <a class="header-anchor" href="#sql-history" aria-label="Permalink to “sql history”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>noorm sql history [--limit &lt;n&gt;] [--config &lt;name&gt;] [--json]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--limit &lt;n&gt;</code>, <code>-n &lt;n&gt;</code></td><td>Entries to show. Default 50</td></tr><tr><td><code>--config &lt;name&gt;</code>, <code>-c &lt;name&gt;</code></td><td>History of this config</td></tr><tr><td><code>--json</code></td><td><code>{&quot;configName&quot;:…,&quot;entries&quot;:[{id, query, executedAt, durationMs, success, errorMessage, rowCount}]}</code></td></tr></tbody></table><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> history</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SQL history for &#39;prod&#39; (2 entries):</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ✓  Oct 21, 01:41:59  12ms · 2 row(s)</span></span>
<span class="line"><span>     SELECT party_id, order_no FROM sales_order LIMIT 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ✗  Oct 21, 01:40:12  4ms · relation &quot;invoice_line&quot; does not exist</span></span>
<span class="line"><span>     SELECT * FROM invoice_line</span></span></code></pre></div><p>Only the interactive SQL terminal (<code>noorm sql repl</code>, or <code>Shift+Q</code> in the TUI) records history. Query text longer than 80 characters is cut with <code>…</code>. History needs a config name but no connection. The name comes from <code>--config</code>, then <code>NOORM_CONFIG</code>, then the active config.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td><code>--limit</code> is not a positive integer</td><td><code>Invalid limit: &lt;value&gt;. Must be a positive integer.</code>, exit 2</td></tr><tr><td>No config named and none active</td><td><code>No config specified and no active config set. Use --config or run &quot;noorm config use &lt;name&gt;&quot;.</code>, exit 2</td></tr><tr><td>Nothing recorded</td><td><code>No SQL history found for config &#39;prod&#39;.</code>, exit 0</td></tr></tbody></table><h2 id="sql-clear" tabindex="-1">sql clear <a class="header-anchor" href="#sql-clear" aria-label="Permalink to “sql clear”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>noorm sql clear [--older-than &lt;months&gt;] [--yes] [--config &lt;name&gt;] [--json]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--older-than &lt;months&gt;</code></td><td>Delete only entries older than this many months</td></tr><tr><td><code>--yes</code>, <code>-y</code></td><td>Delete without the preview step</td></tr><tr><td><code>--config &lt;name&gt;</code>, <code>-c &lt;name&gt;</code></td><td>History of this config</td></tr><tr><td><code>--json</code></td><td>Print <code>{configName, entriesRemoved, filesRemoved}</code>. Also skips the preview step</td></tr></tbody></table><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --older-than</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Cleared 12 entries older than 3 month(s) (4 result files removed).</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Condition</th><th>Behavior</th></tr></thead><tbody><tr><td>Neither <code>--yes</code> nor <code>--json</code></td><td>Prints <code>This will clear all entries from SQL history for config &#39;prod&#39;.</code> and <code>Pass --yes to skip this confirmation.</code>, deletes nothing, exit 0</td></tr><tr><td><code>--json</code> without <code>--yes</code></td><td>Deletes at once</td></tr><tr><td><code>--older-than</code> is not a positive integer</td><td><code>Invalid --older-than value: &lt;value&gt;. Must be a positive integer (months).</code>, exit 2</td></tr><tr><td>No config named and none active</td><td>Same message and exit 2 as <code>history</code></td></tr></tbody></table><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to “Exit codes”">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th><th>Remedy</th></tr></thead><tbody><tr><td>0</td><td>Statement ran, or history was listed or cleared</td><td>None</td></tr><tr><td>1</td><td>Connection failed, the database rejected the statement, role denied, or <code>Unknown command</code></td><td>Read the message. Spell out <code>query</code> when a flag precedes the SQL</td></tr><tr><td>2</td><td>No SQL given, unreadable <code>--file</code>, a bad <code>--limit</code> or <code>--older-than</code>, or no config to read history from</td><td>Fix the argument, or pass <code>--config</code></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/cli/sql-repl.html"><code>noorm sql repl</code></a>: the interactive SQL terminal</li><li><a href="/guide/database/terminal.html">The SQL terminal</a>: history, result browsing, and cancel</li><li><a href="/headless.html#sql">CLI reference</a>: every flag in one place</li></ul>`,27))])}const C=o(p,[["render",g]]);export{q as __pageData,C as default};
